1	<!doctype html>
2	<html lang="en">
3	<head>
4	  <meta charset="utf-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1">
6	  <title>Keep — Edit details prototype</title>
7	  <style>
8	    :root { color-scheme: light; --ink:#17211d; --muted:#68736e; --line:#dce3df; --paper:#fbfcfa; --green:#245c45; --cream:#f3f0e8; }
9	    * { box-sizing: border-box; }
10	    body { margin:0; min-height:100vh; background:var(--paper); color:var(--ink); font:15px/1.5 ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; }
11	    header { height:68px; display:flex; align-items:center; border-bottom:1px solid var(--line); }
12	    .shell { width:min(920px,calc(100% - 48px)); margin:0 auto; }
13	    .brand { display:flex; align-items:center; gap:11px; font-weight:750; font-size:18px; }
14	    .mark { width:29px; height:34px; border-radius:4px 4px 9px 9px; background:var(--green); }
15	    main { padding:64px 0; }
16	    .eyebrow { color:var(--green); font-weight:700; font-size:12px; letter-spacing:.11em; text-transform:uppercase; }
17	    h1 { margin:8px 0 36px; font:600 40px/1.08 Georgia,serif; letter-spacing:-.03em; }
18	    .library-head { display:flex; justify-content:space-between; border-bottom:1px solid var(--line); padding-bottom:13px; }
19	    h2 { margin:0; font-size:17px; }
20	    .count { color:var(--muted); font-size:13px; }
21	    .card { display:grid; grid-template-columns:58px 1fr auto; gap:16px; padding:22px 4px; border-bottom:1px solid var(--line); align-items:start; }
22	    .thumb { width:58px; height:58px; display:grid; place-items:center; border-radius:12px; background:var(--cream); color:var(--green); font:700 22px Georgia,serif; }
23	    .domain { color:var(--green); font-size:12px; font-weight:700; text-transform:uppercase; letter-spacing:.07em; }
24	    .title { margin:3px 0; font:600 20px/1.25 Georgia,serif; }
25	    .summary { margin:0; color:var(--muted); }
26	    button { height:40px; padding:0 15px; border:1px solid #bdc9c2; border-radius:8px; background:white; color:var(--ink); font:650 14px inherit; cursor:pointer; }
27	    button.primary { border-color:var(--green); background:var(--green); color:white; }
28	    .editor { display:none; grid-column:2 / 4; padding:18px; border-radius:11px; background:#f3f6f4; }
29	    .editor.visible { display:block; animation:enter .2s ease-out; }
30	    label { display:block; margin:0 0 6px; font-weight:680; }
31	    input, textarea { width:100%; padding:10px 12px; border:1px solid #bdc9c2; border-radius:8px; background:white; color:var(--ink); font:inherit; }
32	    textarea { min-height:84px; resize:vertical; }
33	    .field + .field { margin-top:14px; }
34	    .actions { display:flex; justify-content:flex-end; gap:8px; margin-top:14px; }
35	    @keyframes enter { from { opacity:0; transform:translateY(-5px); } }
36	    @media(max-width:620px){.shell{width:min(100% - 28px,920px)}.card{grid-template-columns:48px 1fr}.thumb{width:48px;height:48px}.edit-button{grid-column:2}.editor{grid-column:1 / 3}}
37	  </style>
38	</head>
39	<body>
40	  <header><div class="shell brand"><span class="mark" aria-hidden="true"></span><span>Keep</span></div></header>
41	  <main class="shell" data-harness-ready="true">
42	    <div class="eyebrow">Your bookmark library</div>
43	    <h1>All bookmarks</h1>
44	    <section>
45	      <div class="library-head"><h2>Saved</h2><span class="count">1 bookmark</span></div>
46	      <article class="card">
47	        <div class="thumb" aria-hidden="true">A</div>
48	        <div class="details">
49	          <div class="domain">example.com</div>
50	          <h3 class="title" id="shown-title">A practical guide to design systems</h3>
51	          <p class="summary" id="shown-summary">How reusable foundations, components, and shared patterns help teams create consistent digital products.</p>
52	        </div>
53	        <button class="edit-button" id="edit-button" type="button">Edit details</button>
54	        <form class="editor" id="editor">
55	          <div class="field"><label for="title">Title</label><input id="title" value="A practical guide to design systems"></div>
56	          <div class="field"><label for="summary">Summary</label><textarea id="summary">How reusable foundations, components, and shared patterns help teams create consistent digital products.</textarea></div>
57	          <div class="actions"><button id="cancel" type="button">Cancel</button><button class="primary" type="submit">Save changes</button></div>
58	        </form>
59	      </article>
60	    </section>
61	  </main>
62	  <script>
63	    const editor = document.querySelector('#editor');
64	    const edit = document.querySelector('#edit-button');
65	    edit.addEventListener('click', () => { editor.classList.add('visible'); edit.hidden = true; document.querySelector('#title').focus(); });
66	    document.querySelector('#cancel').addEventListener('click', () => { editor.classList.remove('visible'); edit.hidden = false; });
67	    editor.addEventListener('submit', (event) => {
68	      event.preventDefault();
69	      document.querySelector('#shown-title').textContent = document.querySelector('#title').value;
70	      document.querySelector('#shown-summary').textContent = document.querySelector('#summary').value;
71	      editor.classList.remove('visible'); edit.hidden = false;
72	    });
73	  </script>
74	</body>
75	</html>
