9	    .library-head{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding:12px 0}.library-head h2{margin:0;font-size:17px}.count{color:var(--muted);font-size:13px}.card{display:grid;grid-template-columns:52px 1fr auto;gap:15px;padding:20px 4px;border-bottom:1px solid var(--line);align-items:start}.card[hidden]{display:none}.thumb{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;background:var(--cream);color:var(--green);font:700 19px Georgia,serif}.domain{color:var(--green);font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.07em}.title{margin:2px 0;font:600 19px/1.25 Georgia,serif}.summary{margin:0;color:var(--muted);font-size:14px}.actions{display:flex;gap:7px}.card-action{height:34px;padding:0 11px;border:1px solid #bdc9c2;border-radius:8px;background:white;color:var(--ink);font:650 12px inherit;cursor:pointer}.archive{color:#665b31;border-color:#d2caa7;background:#faf8ee}.restore{display:none}.archived .archive{display:none}.archived .restore{display:block}.more-wrap{display:none;position:relative}.menu-mode .more-wrap{display:block}.menu-mode .archive{display:none}.menu-mode .archived .more-wrap{display:none}.more{width:38px;padding:0;font-size:18px}.more-menu{display:none;position:absolute;right:0;top:39px;z-index:3;width:155px;padding:5px;border:1px solid var(--line);border-radius:9px;background:white;box-shadow:0 12px 28px rgba(23,33,29,.15)}.more-menu.visible{display:block}.menu-archive{width:100%;height:35px;padding:0 10px;border:0;border-radius:6px;background:white;color:#665b31;text-align:left;font:650 13px inherit;cursor:pointer}.menu-archive:hover{background:#faf8ee}
