16	  <main class="shell" data-harness-ready="true"><div class="eyebrow">Your bookmark library</div><h1>Find a bookmark</h1><input class="search" placeholder="Search titles, notes, summaries, websites, or tags" aria-label="Search bookmarks">
17	    <div class="controls"><button class="view active" data-view="all">All · <span id="all-count">4</span></button><button class="view" data-view="unread">Unread · 0</button><button class="view" data-view="archived">Archived · <span id="archive-count">0</span></button><span class="spacer"></span><span class="tag-label">Filter by tag</span><button class="tag">design</button><button class="tag">work</button></div>
18	    <section><div class="library-head"><h2 id="list-title">All bookmarks</h2><span class="count" id="list-count">4 bookmarks</span></div><div id="cards">
19	      <article class="card"><div class="thumb">D</div><div><div class="domain">example.com</div><h3 class="title">Design systems, without the jargon</h3><p class="summary">A practical guide to reusable foundations and shared patterns.</p></div><div class="actions"><button class="card-action">Mark unread</button><button class="card-action archive">Archive</button><button class="card-action restore">Restore</button><div class="more-wrap"><button class="card-action more" aria-label="More actions">•••</button><div class="more-menu"><button class="menu-archive">Archive bookmark</button></div></div></div></article>
20	      <article class="card"><div class="thumb">C</div><div><div class="domain">alistapart.com</div><h3 class="title">Colour that works</h3><p class="summary">Building accessible palettes for digital products.</p></div><div class="actions"><button class="card-action">Mark unread</button><button class="card-action archive">Archive</button><button class="card-action restore">Restore</button><div class="more-wrap"><button class="card-action more" aria-label="More actions">•••</button><div class="more-menu"><button class="menu-archive">Archive bookmark</button></div></div></div></article>
21	      <article class="card"><div class="thumb">S</div><div><div class="domain">kitchen.example</div><h3 class="title">Simple sourdough for Saturday</h3><p class="summary">A forgiving bread recipe with an overnight rise.</p></div><div class="actions"><button class="card-action">Mark unread</button><button class="card-action archive">Archive</button><button class="card-action restore">Restore</button><div class="more-wrap"><button class="card-action more" aria-label="More actions">•••</button><div class="more-menu"><button class="menu-archive">Archive bookmark</button></div></div></div></article>
