25	  <script>
26	    const cards=[...document.querySelectorAll('.card')];let view='all';let lastArchived=null;if(new URLSearchParams(location.search).get('mode')==='menu')document.body.classList.add('menu-mode');
27	    function render(){const archived=cards.filter(card=>card.classList.contains('archived'));const active=cards.filter(card=>!card.classList.contains('archived'));cards.forEach(card=>card.hidden=view==='archived'?!card.classList.contains('archived'):card.classList.contains('archived'));const shown=view==='archived'?archived:active;document.querySelector('#archive-count').textContent=archived.length;document.querySelector('#all-count').textContent=active.length;document.querySelector('#list-title').textContent=view==='archived'?'Archived bookmarks':'All bookmarks';document.querySelector('#list-count').textContent=`${shown.length} ${shown.length===1?'bookmark':'bookmarks'}`;document.querySelector('#empty').classList.toggle('visible',shown.length===0);document.querySelectorAll('.view').forEach(button=>button.classList.toggle('active',button.dataset.view===view));}
28	    document.querySelectorAll('.archive,.menu-archive').forEach(button=>button.addEventListener('click',()=>{lastArchived=button.closest('.card');lastArchived.classList.add('archived');document.querySelector('#toast').classList.add('visible');document.querySelectorAll('.more-menu').forEach(menu=>menu.classList.remove('visible'));render()}));
29	    document.querySelectorAll('.more').forEach(button=>button.addEventListener('click',()=>{const menu=button.nextElementSibling;document.querySelectorAll('.more-menu').forEach(other=>{if(other!==menu)other.classList.remove('visible')});menu.classList.toggle('visible')}));
30	    document.querySelectorAll('.restore').forEach(button=>button.addEventListener('click',()=>{button.closest('.card').classList.remove('archived');render()}));
31	    document.querySelectorAll('.view').forEach(button=>button.addEventListener('click',()=>{view=button.dataset.view;render()}));
32	    document.querySelector('#undo').addEventListener('click',()=>{if(lastArchived)lastArchived.classList.remove('archived');document.querySelector('#toast').classList.remove('visible');render()});
33	  </script>
