6	    :root{color-scheme:light;--ink:#17211d;--muted:#68736e;--line:#dce3df;--paper:#fbfcfa;--green:#245c45;--cream:#f3f0e8;--red:#a33a31;--red-soft:#fff1ef;--amber:#7b641f;--amber-soft:#fff8df}
