bottom:1px solid var(--line);align-items:start}.card.visible{display:grid}.thumb{width:54px;height:54px;display:grid;place-items:center;border-radius:11px;background:var(--cream);color:var(--green);font:700 20px Georgia,serif}.domain{color:var(--green);font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.07em}.title{margin:2px 0;font:600 19px/1.25 Georgia,serif}.summary{margin:0;color:var(--muted);font-size:14px}.edit{height:34px;padding:0 11px;border:1px solid #bdc9c2;background:white;color:var(--ink);font-size:12px}.match{font-size:12px;color:var(--green);font-weight:700}@media(max-width:620px){.shell{width:min(100% - 28px,920px)}.row{flex-direction:column}button{width:100%}.card{grid-template-columns:48px 1fr}.edit{grid-column:2;width:auto;justify-self:start}}
