10	<body><header><div class="shell brand"><span class="mark"></span><span>Keep</span></div></header>
11	  <main class="shell" data-harness-ready="true"><div class="eyebrow">Your bookmark library</div><h1>Save a bookmark</h1><p class="intro">Paste a useful corner of the web. We’ll gather the details.</p>
12	    <form class="add-panel" id="form"><label for="url">Web address</label><div class="row"><input id="url" autocomplete="off"><button type="submit" id="save">Save bookmark</button></div><p class="hint">Use the complete address, beginning with http:// or https://</p><div class="message" id="message" role="alert"></div></form>
13	    <section class="library"><div class="library-head"><h2>All bookmarks</h2><span class="count" id="count">0 bookmarks</span></div><div class="empty" id="empty">Your saved bookmarks will appear here.</div><article class="card" id="card"><div class="thumb">S</div><div><div class="domain" id="domain">smallsite.example</div><h3 class="title" id="title">smallsite.example/article</h3><p class="summary" id="summary">Page details weren’t available. You can add your own title and summary.</p><span class="match" id="match"></span></div><button class="edit" type="button">Edit details</button></article></section>
14	  </main>
15	  <script>
16	    const mode=new URLSearchParams(location.search).get('case')||'invalid';const input=document.querySelector('#url');const message=document.querySelector('#message');const card=document.querySelector('#card');const empty=document.querySelector('#empty');const count=document.querySelector('#count');
17	    if(mode==='invalid')input.value='not-a-web-address';
18	    if(mode==='metadata')input.value='https://smallsite.example/article';
19	    if(mode==='duplicate'){input.value='https://example.com/design-systems';card.classList.add('visible');empty.hidden=true;count.textContent='1 bookmark';document.querySelector('#domain').textContent='example.com';document.querySelector('#title').textContent='Design systems, without the jargon';document.querySelector('#summary').textContent='A practical guide to reusable foundations and shared patterns.';}
20	    document.querySelector('#form').addEventListener('submit',event=>{event.preventDefault();message.className='message';input.classList.remove('error');
21	      if(mode==='invalid'){input.classList.add('error');message.textContent='Enter a complete web address, like https://example.com/article';message.classList.add('visible','error');input.focus();return;}
22	      if(mode==='duplicate'){message.textContent='Already saved: Design systems, without the jargon';message.classList.add('visible','warning');document.querySelector('#match').textContent='This is the bookmark you already saved.';return;}
23	      message.textContent='We couldn’t retrieve this page’s title or summary. The bookmark was still saved, and you can add those details yourself.';message.classList.add('visible','warning');card.classList.add('visible');empty.hidden=true;count.textContent='1 bookmark';
24	    });
25	  </script>
26	</body></html>
